'use client';

import { useInstrument } from '../../theme/theme-provider';
import { formatPrice } from '../../format';
import { usePriceFlash } from '../../hooks';
import type { Instrument, Side } from '../../types';
import { cn } from '../../utils';

export interface BuySellButtonsProps {
  bid: number;
  ask: number;
  instrument?: Partial<Instrument>;
  /** Size shown on each button, e.g. `1.00` lots or `100` shares. */
  quantity?: number;
  /** Unit label beside the quantity. */
  quantityLabel?: string;
  /** Spread block between the two sides. */
  showSpread?: boolean;
  /** Spread in ticks rather than price. */
  spreadInTicks?: boolean;
  disabled?: boolean;
  size?: 'sm' | 'default' | 'lg';
  onTrade?: (side: Side, price: number) => void;
  className?: string;
}

const SIZES = {
  sm: { price: 'text-base', label: 'text-[9px]', pad: 'px-3 py-1.5' },
  default: { price: 'text-xl', label: 'text-[10px]', pad: 'px-4 py-2.5' },
  lg: { price: 'text-2xl', label: 'text-[11px]', pad: 'px-5 py-3.5' },
} as const;

/**
 * The one-click dealing buttons from an FX or CFD front end: sell at the bid on
 * the left, buy at the offer on the right, spread between them.
 *
 * Sell is on the left and buy on the right because that is the order a book is
 * drawn in, and muscle memory on a dealing desk is built on position, not on
 * reading the label. The price on each button is the price you get, which is
 * why it flashes on change rather than updating silently — a button whose value
 * changed under your cursor should say so before you click it.
 */
export function BuySellButtons({
  bid,
  ask,
  instrument,
  quantity,
  quantityLabel,
  showSpread = true,
  spreadInTicks = false,
  disabled = false,
  size = 'default',
  onTrade,
  className,
}: BuySellButtonsProps) {
  const inst = useInstrument(instrument);
  const bidFlash = usePriceFlash(bid);
  const askFlash = usePriceFlash(ask);
  const s = SIZES[size];

  const spread = ask - bid;
  const spreadText = spreadInTicks
    ? `${Math.round(spread / inst.tickSize)}`
    : formatPrice(spread, inst.pricePrecision);

  // The big figure is the part that rarely moves; the last two digits are what
  // the eye tracks, so they are the ones rendered large.
  const renderPrice = (value: number, flash: string) => {
    const text = formatPrice(value, inst.pricePrecision);
    const split = Math.max(0, text.length - 2);
    return (
      <span
        className={cn(
          'rounded-sm font-mono leading-none font-semibold tabular-nums',
          s.price,
          flash === 'up' && 'animate-flash-up',
          flash === 'down' && 'animate-flash-down',
        )}
      >
        <span className="opacity-70">{text.slice(0, split)}</span>
        {text.slice(split)}
      </span>
    );
  };

  const side = (which: Side) => {
    const isBuy = which === 'buy';
    const price = isBuy ? ask : bid;
    return (
      <button
        type="button"
        disabled={disabled}
        onClick={() => onTrade?.(which, price)}
        aria-label={`${isBuy ? 'Buy' : 'Sell'} at ${formatPrice(price, inst.pricePrecision)}`}
        className={cn(
          'focus-visible:ring-ring flex flex-1 cursor-pointer flex-col items-center gap-1 transition-colors outline-none focus-visible:ring-2 focus-visible:ring-inset',
          'disabled:cursor-not-allowed disabled:opacity-50',
          s.pad,
          isBuy
            ? 'bg-up/15 text-up hover:bg-up/25 active:bg-up/35'
            : 'bg-down/15 text-down hover:bg-down/25 active:bg-down/35',
        )}
      >
        <span className={cn('font-semibold tracking-[0.12em] uppercase opacity-80', s.label)}>
          {isBuy ? 'Buy' : 'Sell'}
        </span>
        {renderPrice(price, isBuy ? askFlash : bidFlash)}
        {quantity !== undefined && (
          <span className={cn('font-mono tabular-nums opacity-60', s.label)}>
            {quantity}
            {quantityLabel ? ` ${quantityLabel}` : ''}
          </span>
        )}
      </button>
    );
  };

  return (
    <div
      className={cn(
        'border-border bg-card flex items-stretch overflow-hidden rounded-lg border',
        className,
      )}
    >
      {side('sell')}
      {showSpread && (
        <div className="bg-muted text-muted-foreground flex min-w-12 flex-col items-center justify-center gap-0.5 border-x px-2">
          <span className="text-[9px] tracking-wider uppercase">Spread</span>
          <span className="text-foreground font-mono text-xs font-semibold tabular-nums">
            {spreadText}
          </span>
        </div>
      )}
      {side('buy')}
    </div>
  );
}

import type { Direction } from './types';

/**
 * Formatting helpers. Every number shown in a trading UI is formatted the same
 * way twice: fixed decimals so digits line up in a tabular-nums column, and an
 * explicit sign where direction matters.
 */

const cache = new Map<string, Intl.NumberFormat>();

function nf(min: number, max: number, extra?: Intl.NumberFormatOptions) {
  const key = `${min}:${max}:${extra ? JSON.stringify(extra) : ''}`;
  let f = cache.get(key);
  if (!f) {
    f = new Intl.NumberFormat('en-US', {
      minimumFractionDigits: min,
      maximumFractionDigits: max,
      ...extra,
    });
    cache.set(key, f);
  }
  return f;
}

/** `1234.5` at precision 2 -> `"1,234.50"`. */
export function formatPrice(value: number, precision = 2): string {
  if (!Number.isFinite(value)) return '--';
  return nf(precision, precision).format(value);
}

/** Quantity: grouped, trailing zeros trimmed. */
export function formatQuantity(value: number, precision = 0): string {
  if (!Number.isFinite(value)) return '--';
  return nf(0, precision).format(value);
}

/** `1250000` -> `"1.25M"`. Keeps size columns to four glyphs. */
export function formatCompact(value: number, digits = 2): string {
  if (!Number.isFinite(value)) return '--';
  const abs = Math.abs(value);
  const sign = value < 0 ? '-' : '';
  const units: Array<[number, string]> = [
    [1e12, 'T'],
    [1e9, 'B'],
    [1e6, 'M'],
    [1e3, 'K'],
  ];
  for (const [scale, suffix] of units) {
    if (abs >= scale) {
      const scaled = abs / scale;
      // Keep three significant digits: 1.25M, 12.5M, 125M.
      const d = scaled >= 100 ? 0 : scaled >= 10 ? 1 : digits;
      return `${sign}${nf(0, d).format(scaled)}${suffix}`;
    }
  }
  return `${sign}${nf(0, abs < 1 ? digits : 0).format(abs)}`;
}

/** `0.0421` -> `"+4.21%"`. Input is a ratio, not percentage points. */
export function formatPercent(ratio: number, precision = 2, signed = true): string {
  if (!Number.isFinite(ratio)) return '--';
  const pct = ratio * 100;
  const sign = signed && pct > 0 ? '+' : '';
  return `${sign}${nf(precision, precision).format(pct)}%`;
}

/** Absolute change with a forced sign so gains and losses align. */
export function formatSigned(value: number, precision = 2): string {
  if (!Number.isFinite(value)) return '--';
  const sign = value > 0 ? '+' : '';
  return `${sign}${nf(precision, precision).format(value)}`;
}

/** `hh:mm:ss` in local time - the tape's only useful resolution. */
export function formatTime(time: number | Date, withMillis = false): string {
  const d = time instanceof Date ? time : new Date(time);
  const base = d.toTimeString().slice(0, 8);
  if (!withMillis) return base;
  return `${base}.${String(d.getMilliseconds()).padStart(3, '0')}`;
}

/** Axis-friendly timestamp: drops seconds, adds the date when it changes. */
export function formatAxisTime(time: number, showDate = false): string {
  const d = new Date(time);
  const hhmm = d.toTimeString().slice(0, 5);
  if (!showDate) return hhmm;
  return `${d.getMonth() + 1}/${d.getDate()}`;
}

/** Signed money, e.g. `-$1,204.50`. */
export function formatMoney(value: number, currency = '$', precision = 2): string {
  if (!Number.isFinite(value)) return '--';
  const sign = value < 0 ? '-' : '';
  return `${sign}${currency}${nf(precision, precision).format(Math.abs(value))}`;
}

/** Direction of `value` relative to `reference` (default zero). */
export function directionOf(value: number, reference = 0): Direction {
  if (!Number.isFinite(value) || value === reference) return 'flat';
  return value > reference ? 'up' : 'down';
}

/** The `tu-up` / `tu-down` / `tu-flat` class for a direction. */
export function directionClass(direction: Direction): string {
  return `tu-${direction}`;
}

/** `+` / `-` glyphs used by DeltaBadge and the tape. */
export function directionArrow(direction: Direction): string {
  return direction === 'up' ? '▲' : direction === 'down' ? '▼' : '–';
}

/** Round to the instrument's tick so UI-entered prices are always valid. */
export function roundToTick(price: number, tickSize: number): number {
  if (!tickSize || tickSize <= 0) return price;
  const ticks = Math.round(price / tickSize);
  // Re-round after dividing to shake off float dust (0.1 * 3 = 0.30000000000000004).
  const decimals = decimalsOf(tickSize);
  return Number((ticks * tickSize).toFixed(decimals));
}

/** Decimal places implied by a tick size: `0.01` -> 2, `0.5` -> 1, `5` -> 0. */
export function decimalsOf(tickSize: number): number {
  if (!Number.isFinite(tickSize) || tickSize <= 0) return 2;
  const s = tickSize.toString();
  if (s.includes('e-')) return Number(s.split('e-')[1]);
  const dot = s.indexOf('.');
  return dot === -1 ? 0 : s.length - dot - 1;
}

/** Shared domain types. Deliberately plain so any feed can map onto them. */

export type Side = 'buy' | 'sell';
export type Direction = 'up' | 'down' | 'flat';

/** One OHLCV bar. `time` is epoch milliseconds at the bar's open. */
export interface Candle {
  time: number;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
}

/** A single price level in the book. */
export interface BookLevel {
  price: number;
  size: number;
}

export interface OrderBookSnapshot {
  /** Highest price first. */
  bids: BookLevel[];
  /** Lowest price first. */
  asks: BookLevel[];
}

export interface Trade {
  id: string;
  time: number;
  price: number;
  size: number;
  /** Aggressor side: `buy` means it lifted the offer. */
  side: Side;
}

export interface Quote {
  symbol: string;
  name?: string;
  last: number;
  /** Previous session close, used for the day change. */
  prevClose: number;
  bid?: number;
  ask?: number;
  dayHigh?: number;
  dayLow?: number;
  volume?: number;
  /** Optional intraday series for an inline sparkline. */
  history?: number[];
}

export interface Position {
  symbol: string;
  /** Signed: negative is short. */
  quantity: number;
  avgPrice: number;
  markPrice: number;
}

export type OrderType = 'market' | 'limit' | 'stop' | 'stop-limit';
export type OrderStatus = 'working' | 'filled' | 'partial' | 'cancelled' | 'rejected';

export interface OrderDraft {
  symbol: string;
  side: Side;
  type: OrderType;
  quantity: number;
  /** Required for limit / stop-limit. */
  limitPrice?: number;
  /** Required for stop / stop-limit. */
  stopPrice?: number;
  timeInForce: TimeInForce;
}

export type TimeInForce = 'day' | 'gtc' | 'ioc' | 'fok';

export interface Order extends OrderDraft {
  id: string;
  time: number;
  status: OrderStatus;
  filledQuantity: number;
  avgFillPrice?: number;
}

/** Price/size formatting rules for an instrument. */
export interface Instrument {
  symbol: string;
  name?: string;
  /** Decimal places for price. */
  pricePrecision: number;
  /** Minimum price increment. */
  tickSize: number;
  /** Decimal places for quantity. */
  sizePrecision?: number;
  /** Quote-currency symbol, e.g. "$". */
  currency?: string;
}

/**
 * One execution. Distinct from an `Order`: an order is an instruction, a fill
 * is what actually happened to it, and a single order can produce many fills
 * at different prices. Reconciliation, cost basis and fee accounting all work
 * off fills, never off orders.
 */
export interface Fill {
  id: string;
  /** The order this execution belongs to, for grouping a partial sequence. */
  orderId?: string;
  symbol: string;
  time: number;
  side: Side;
  quantity: number;
  price: number;
  /** Commission or exchange fee, in the quote currency. Negative is a rebate. */
  fee?: number;
  /** `maker` rested and was hit; `taker` crossed the spread. Drives the fee. */
  liquidity?: 'maker' | 'taker';
  venue?: string;
}

'use client';

import { useEffect, useLayoutEffect, useRef, useState } from 'react';
import type { Direction } from './types';

/**
 * Measures an element with ResizeObserver. Canvas charts need real pixel
 * dimensions, and in a resizable terminal layout those change constantly.
 */
export function useElementSize<T extends HTMLElement>() {
  const ref = useRef<T | null>(null);
  const [size, setSize] = useState({ width: 0, height: 0 });

  useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;

    const read = () => {
      const rect = el.getBoundingClientRect();
      setSize((prev) =>
        // Sub-pixel churn would re-render on every scroll of a parent.
        Math.abs(prev.width - rect.width) < 0.5 &&
        Math.abs(prev.height - rect.height) < 0.5
          ? prev
          : { width: rect.width, height: rect.height },
      );
    };

    read();
    if (typeof ResizeObserver === 'undefined') return;
    const ro = new ResizeObserver(read);
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  return [ref, size] as const;
}

/**
 * Reports which way a value last moved and clears back to `flat` after
 * `duration`, so a price cell can flash green/red on each tick.
 */
export function usePriceFlash(value: number, duration = 420): Direction {
  const previous = useRef(value);
  const [flash, setFlash] = useState<Direction>('flat');

  useEffect(() => {
    const prev = previous.current;
    previous.current = value;
    if (!Number.isFinite(value) || !Number.isFinite(prev) || value === prev) return;

    setFlash(value > prev ? 'up' : 'down');
    const t = setTimeout(() => setFlash('flat'), duration);
    return () => clearTimeout(t);
  }, [value, duration]);

  return flash;
}

/** The value from the previous render - handy for diffing feed snapshots. */
export function usePrevious<T>(value: T): T | undefined {
  const ref = useRef<T | undefined>(undefined);
  useEffect(() => {
    ref.current = value;
  }, [value]);
  return ref.current;
}

/**
 * requestAnimationFrame loop that stays mounted across re-renders. Used by the
 * mock feed and by chart crosshair redraws; `fps` throttles it.
 */
export function useAnimationFrame(callback: (dt: number) => void, fps = 60) {
  const cb = useRef(callback);
  cb.current = callback;

  useEffect(() => {
    if (fps <= 0) return;
    let raf = 0;
    let last = performance.now();
    const minDelta = 1000 / fps;

    const tick = (now: number) => {
      raf = requestAnimationFrame(tick);
      const dt = now - last;
      if (dt < minDelta) return;
      last = now;
      cb.current(dt);
    };

    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [fps]);
}

/** True when the user has asked the OS to reduce motion. */
export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    if (typeof matchMedia !== 'function') return;
    const mq = matchMedia('(prefers-reduced-motion: reduce)');
    setReduced(mq.matches);
    const onChange = (e: MediaQueryListEvent) => setReduced(e.matches);
    mq.addEventListener('change', onChange);
    return () => mq.removeEventListener('change', onChange);
  }, []);
  return reduced;
}

'use client';

import {
  createContext,
  useContext,
  useMemo,
  type CSSProperties,
  type ReactNode,
} from 'react';
import { TooltipProvider } from '../components/ui/tooltip';
import type { Instrument } from '../types';
import { cn } from '../utils';

export type ThemeName = 'dark' | 'light';
export type DirectionPalette = 'classic' | 'colorblind';

export interface TradingTheme {
  theme: ThemeName;
  /** `classic` is green/red; `colorblind` is blue/amber. */
  palette: DirectionPalette;
  /** Formatting defaults for components not given their own instrument. */
  instrument: Instrument;
}

export const defaultInstrument: Instrument = {
  symbol: '',
  pricePrecision: 2,
  tickSize: 0.01,
  sizePrecision: 0,
  currency: '$',
};

const ThemeContext = createContext<TradingTheme>({
  theme: 'dark',
  palette: 'classic',
  instrument: defaultInstrument,
});

export function useTradingTheme(): TradingTheme {
  return useContext(ThemeContext);
}

/**
 * Resolves the instrument a component formats with: its own prop wins, then
 * the provider's, then the library default.
 */
export function useInstrument(override?: Partial<Instrument>): Instrument {
  const { instrument } = useTradingTheme();
  return useMemo(
    () => (override ? { ...instrument, ...override } : instrument),
    [instrument, override],
  );
}

export interface TradingProviderProps {
  children: ReactNode;
  theme?: ThemeName;
  palette?: DirectionPalette;
  instrument?: Partial<Instrument>;
  /** Token overrides, e.g. `{ '--primary': '#ff8a00' }`. */
  tokens?: Record<string, string>;
  /**
   * Skip the wrapper element and inherit whatever theme the host already
   * applies. Use this inside an existing shadcn app that owns `.dark` itself.
   */
  inherit?: boolean;
  className?: string;
  style?: CSSProperties;
}

/**
 * Scopes theme, direction palette and instrument defaults to a subtree.
 *
 * Deliberately not a global stylesheet switch: two providers can coexist, so a
 * light-themed report can sit inside a dark terminal. Also mounts a single
 * Radix TooltipProvider so every tooltip in the tree shares one delay timer.
 */
export function TradingProvider({
  children,
  theme = 'dark',
  palette = 'classic',
  instrument,
  tokens,
  inherit = false,
  className,
  style,
}: TradingProviderProps) {
  const value = useMemo<TradingTheme>(
    () => ({ theme, palette, instrument: { ...defaultInstrument, ...instrument } }),
    [theme, palette, instrument],
  );

  const content = <TooltipProvider>{children}</TooltipProvider>;

  return (
    <ThemeContext.Provider value={value}>
      {inherit ? (
        content
      ) : (
        <div
          data-tu-theme={theme}
          data-tu-palette={palette}
          className={cn(
            'bg-background text-foreground',
            theme === 'dark' && 'dark',
            className,
          )}
          style={{ ...(tokens as CSSProperties | undefined), ...style }}
        >
          {content}
        </div>
      )}
    </ThemeContext.Provider>
  );
}

import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

/**
 * Merge Tailwind classes with later ones winning - the same `cn` shadcn/ui
 * uses, so a consumer can override any class on any component by passing
 * `className`, with no specificity war.
 */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/** Shared empty array, so a normalized-away prop keeps a stable identity and
 *  does not invalidate the `useMemo` that depends on it on every render. */
const EMPTY: readonly never[] = Object.freeze([]);

/**
 * Coerces a feed-supplied collection to something safe to iterate.
 *
 * A live feed is not a type system. Sockets drop fields, REST returns `null`
 * for "no rows yet", and a panel mounts before its first payload lands. None
 * of that should unmount the React tree — a component with nothing to show
 * renders its empty state instead. Returns a frozen shared array when the
 * input is unusable, so the identity stays stable across renders.
 */
export function toArray<T>(value: readonly T[] | null | undefined): readonly T[] {
  return Array.isArray(value) ? value : (EMPTY as readonly T[]);
}

/** `toArray` for both sides of a book, tolerating a missing snapshot entirely. */
export function toBook<T>(book: { bids?: readonly T[] | null; asks?: readonly T[] | null } | null | undefined) {
  return { bids: toArray(book?.bids), asks: toArray(book?.asks) };
}
